export interface EpisodeRecap {
  podcastSlug: string;
  episodeSlug: string;
  episodeTitle: string;
  publishDate: string;
  duration: string;
  artworkUrl: string;
  podcastName: string;
  hosts: string;
  tldl: string;
  whatHappened: string;
  keyInsights: string[];
  quote?: string;
  quoteAttribution?: string;
}

function slugify(title: string): string {
  return title
    .toLowerCase()
    .replace(/['']/g, "")
    .replace(/[^a-z0-9\s-]/g, "")
    .replace(/\s+/g, "-")
    .replace(/-+/g, "-")
    .replace(/^-|-$/g, "")
    .split("-")
    .slice(0, 8)
    .join("-");
}

