export function getRecapsByPodcast(podcastSlug: string): EpisodeRecap[] {
  return EPISODE_RECAPS.filter(r => r.podcastSlug === podcastSlug);
}

export function getEpisodesByPodcast(podcastSlug: string): EpisodeRecap[] {
  return EPISODE_RECAPS.filter(r => r.podcastSlug === podcastSlug);
}

export function getEpisodesByPodcastPaginated(podcastSlug: string, page: number, perPage: number): { episodes: EpisodeRecap[]; totalPages: number; total: number } {
  const all = EPISODE_RECAPS.filter(r => r.podcastSlug === podcastSlug);
  const total = all.length;
  const totalPages = Math.ceil(total / perPage);
  const start = (page - 1) * perPage;
  const episodes = all.slice(start, start + perPage);
  return { episodes, totalPages, total };
}

export function getRecapBySlug(podcastSlug: string, episodeSlug: string): EpisodeRecap | undefined {
  return EPISODE_RECAPS.find(r => r.podcastSlug === podcastSlug && r.episodeSlug === episodeSlug);
}

export function getEpisodeBySlug(podcastSlug: string, episodeSlug: string): EpisodeRecap | undefined {
  return EPISODE_RECAPS.find(r => r.podcastSlug === podcastSlug && r.episodeSlug === episodeSlug);
}

export function getAdjacentEpisodes(podcastSlug: string, episodeSlug: string): { prev: EpisodeRecap | null; next: EpisodeRecap | null } {
  const episodes = EPISODE_RECAPS.filter(r => r.podcastSlug === podcastSlug);
  const idx = episodes.findIndex(r => r.episodeSlug === episodeSlug);
  return {
    prev: idx < episodes.length - 1 ? episodes[idx + 1] : null,
    next: idx > 0 ? episodes[idx - 1] : null,
  };
}

export function getAllRecaps(): EpisodeRecap[] {
  return EPISODE_RECAPS;
}